mapper.select:
select from lab_device d inner join lab_laboratory l on l.id = d.laboratory_id and l.del_flag = '0' where d.del_flag = '0'
and d.laboratory_id = #{laboratoryId}
and d.category_code = #{categoryCode}
and d.status = #{status}
and (d.asset_no like concat('%', #{keyword}, '%') or d.name like concat('%', #{keyword}, '%') or d.model like concat('%', #{keyword}, '%') or d.location like concat('%', #{keyword}, '%'))
order by ${sort.column} ${sort.direction}, d.id asc
order by d.create_time desc

mapper.update:
update lab_device
set status = #{target},
    version = version + 1
where id = #{deviceId}
  and status = #{expected}
  and del_flag = '0'
